}
function navArrow(s){
  const m = (s.maneuver || {}).modifier, t = (s.maneuver || {}).type;
  if (t === 'arrive') return '🏁'; if (t === 'roundabout' || t === 'rotary') return '⟳';
  return {'left':'⬅', 'sharp left':'⬅', 'slight left':'↖', 'right':'➡', 'sharp right':'➡', 'slight right':'↗', 'uturn':'↩'}[m] || '⬆';
}
function navLineDist(ll){ const c = NAV.r.geometry.coordinates; let b = 1e9; for (let i = 1; i < c.length; i++) { const d = segDist(ll, c[i - 1], c[i]); if (d < b) b = d; } return b; }
function navUI(){
